import{_ as t,o as a,c as o,a2 as r}from"./chunks/framework.CyZTVJbV.js";const u=JSON.parse('{"title":"x.com draft — English thread (v1.4 polyglot completion voice)","description":"","frontmatter":{},"headers":[],"relativePath":"announcements/v1.4/x-thread-en.md","filePath":"announcements/v1.4/x-thread-en.md"}'),d={name:"announcements/v1.4/x-thread-en.md"};function i(s,e,n,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="x-com-draft-—-english-thread-v1-4-polyglot-completion-voice" tabindex="-1">x.com draft — English thread (v1.4 polyglot completion voice) <a class="header-anchor" href="#x-com-draft-—-english-thread-v1-4-polyglot-completion-voice" aria-label="Permalink to &quot;x.com draft — English thread (v1.4 polyglot completion voice)&quot;">​</a></h1><blockquote><p>Posting from ... <a href="https://x.com/cardene777" target="_blank" rel="noreferrer">@cardene777</a> Voice ... first-person / solo dev / &quot;v0.5 promise delivered&quot; maker tone Video ... <code>assets/kiwa-promo-en.mp4</code> (reused) attached to tweet 1 Limit ... 280 chars per tweet Thread of 8 tweets, numbered [1/8]</p></blockquote><hr><h2 id="_1-8-video-attached" tabindex="-1">[1/8] (video attached) <a class="header-anchor" href="#_1-8-video-attached" aria-label="Permalink to &quot;[1/8] (video attached)&quot;">​</a></h2><p>kiwa v1.4 just landed (6/6 Issue resolved) — Rust + Go adapters complete the <strong>5-language polyglot</strong> lineup (TS / Python / Solidity + Rust + Go).</p><p>This finally delivers on the &quot;Rust / Go coming&quot; promise from the v0.5 announcement.</p><p><a href="https://github.com/cardene777/kiwa" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa</a></p><p>#OSS #testing</p><hr><h2 id="_2-8" tabindex="-1">[2/8] <a class="header-anchor" href="#_2-8" aria-label="Permalink to &quot;[2/8]&quot;">​</a></h2><p>What grew in v1.4:</p><ul><li>Languages: 3 → 5 (+ Rust + Go)</li><li>Skills: 25 → 27 (+ kiwa-rust + kiwa-go)</li><li>Layer 1 spec layers: 9 → 13 (+ 4 polyglot layers)</li><li>Cross-language packages: 1 PyPI → 3 (PyPI + crates.io + pkg.go.dev)</li></ul><hr><h2 id="_3-8" tabindex="-1">[3/8] <a class="header-anchor" href="#_3-8" aria-label="Permalink to &quot;[3/8]&quot;">​</a></h2><p>Rust (kiwa-test-rs v0.1):</p><ul><li><code>cargo test</code> adapter (unit, <code>setup_env</code> + <code>assert_kiwa_eq!</code> / <code>assert_kiwa_close!</code>)</li><li><code>hyper</code> mock_server (integration, <code>RecordedRequest</code> capture)</li><li><code>integration</code> feature default ON, opt-out for unit-only users</li></ul><hr><h2 id="_4-8" tabindex="-1">[4/8] <a class="header-anchor" href="#_4-8" aria-label="Permalink to &quot;[4/8]&quot;">​</a></h2><p>Go (kiwa-test-go v0.1):</p><ul><li><code>testing.T</code> adapter (<code>SetupUnitEnv</code> + <code>t.Cleanup</code> auto-stop)</li><li><code>httptest.Server</code> wrap (integration, stdlib zero-dep)</li><li><code>testing.TB</code> accept — <code>T</code> / <code>B</code> / <code>F</code> all supported, race-detector clean</li></ul><hr><h2 id="_5-8" tabindex="-1">[5/8] <a class="header-anchor" href="#_5-8" aria-label="Permalink to &quot;[5/8]&quot;">​</a></h2><p><code>/kiwa-design</code> adds 4 layers (<code>rust-unit</code> / <code>rust-integration</code> / <code>go-unit</code> / <code>go-integration</code>).</p><p>One feature → 5-language spec → parallel <code>/kiwa-rust</code> + <code>/kiwa-go</code> test generation.</p><hr><h2 id="_6-8" tabindex="-1">[6/8] <a class="header-anchor" href="#_6-8" aria-label="Permalink to &quot;[6/8]&quot;">​</a></h2><p>The &quot;scattered test stack&quot; problem isn&#39;t just runners — it&#39;s <strong>languages too</strong>.</p><p>In a typical dApp: Solidity / TS / Python / Rust crypto lib / Go gateway all coexist. Driving them from one spec is the polyglot point.</p><hr><h2 id="_7-8" tabindex="-1">[7/8] <a class="header-anchor" href="#_7-8" aria-label="Permalink to &quot;[7/8]&quot;">​</a></h2><p>Stats:</p><table tabindex="0"><thead><tr><th>Axis</th><th>v1.3</th><th>v1.4</th></tr></thead><tbody><tr><td>Languages</td><td>3</td><td><strong>5</strong></td></tr><tr><td>Skills</td><td>25</td><td>27</td></tr><tr><td>Layer 1 spec layers</td><td>9</td><td>13</td></tr></tbody></table><p>5-language polyglot reached. dApps + web + libs + services all driven from one spec.</p><hr><h2 id="_8-8" tabindex="-1">[8/8] <a class="header-anchor" href="#_8-8" aria-label="Permalink to &quot;[8/8]&quot;">​</a></h2><p>v1.5 candidates: Rust / Go web framework adapters (axum / actix / Gin / Echo) + new layers (auth / job queue / cache).</p><p>Drop requests on GitHub Discussions:</p><p><a href="https://github.com/cardene777/kiwa/discussions" target="_blank" rel="noreferrer">https://github.com/cardene777/kiwa/discussions</a></p><p>#testing #rustlang #golang</p>',39)])])}const g=t(d,[["render",i]]);export{u as __pageData,g as default};
